     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→// 난이도별 물리적 최대 점수 (2시간 연속 플레이 기준)
     9→const SCORE_CAPS: Record<string, number> = {
    10→  easy: 10000,
    11→  normal: 15000,
    12→  hard: 20000,
    13→  extreme: 30000,
    14→  physical: 30000,
    15→};
    16→
    17→Deno.serve(async (req: Request) => {
    18→  if (req.method === 'OPTIONS') {
    19→    return new Response('ok', { headers: corsHeaders });
    20→  }
    21→
    22→  try {
    23→    const { score, difficulty, userName, sessionId, verification, characterType } = await req.json();
    24→
    25→    // 기본 입력 검증
    26→    if (typeof score !== 'number' || score < 0) {
    27→      return new Response(
    28→        JSON.stringify({ error: 'Invalid score' }),
    29→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    30→      );
    31→    }
    32→
    33→    const validDifficulties = ['easy', 'normal', 'hard', 'extreme', 'physical'];
    34→    if (!validDifficulties.includes(difficulty)) {
    35→      return new Response(
    36→        JSON.stringify({ error: 'Invalid difficulty' }),
    37→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    38→      );
    39→    }
    40→
    41→    if (!userName || !/^[A-Z]{3}$/.test(userName)) {
    42→      return new Response(
    43→        JSON.stringify({ error: 'Invalid userName: must be 3 uppercase letters' }),
    44→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    45→      );
    46→    }
    47→
    48→    // 하드 캡: 물리적으로 불가능한 점수 차단
    49→    if (score > (SCORE_CAPS[difficulty] ?? 10000)) {
    50→      console.warn('Score exceeds hard cap', { score, difficulty });
    51→      return new Response(
    52→        JSON.stringify({ error: 'Score exceeds maximum possible value' }),
    53→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    54→      );
    55→    }
    56→
    57→    // JWT 인증
    58→    const authHeader = req.headers.get('Authorization');
    59→    if (!authHeader) {
    60→      return new Response(
    61→        JSON.stringify({ error: 'Missing authorization header' }),
    62→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    63→      );
    64→    }
    65→
    66→    const supabaseUser = createClient(
    67→      Deno.env.get('SUPABASE_URL') ?? '',
    68→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    69→      { global: { headers: { Authorization: authHeader } } }
    70→    );
    71→
    72→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    73→    if (authError || !user) {
    74→      return new Response(
    75→        JSON.stringify({ error: 'Unauthorized' }),
    76→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    77→      );
    78→    }
    79→
    80→    const supabaseAdmin = createClient(
    81→      Deno.env.get('SUPABASE_URL') ?? '',
    82→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    83→    );
    84→
    85→    // ── 세션 검증: 서버가 기록한 start_time 기준으로 경과 시간 확인 ──────────
    86→    // UPDATE WHERE used=false RETURNING ... 패턴으로 원자적 검증 + 소비 처리
    87→    // SELECT 후 UPDATE 방식은 동시 요청 시 race condition 가능 → 이 방식으로 방지
    88→    if (sessionId) {
    89→      const { data: session } = await supabaseAdmin
    90→        .from('game_sessions')
    91→        .update({ used: true })
    92→        .eq('id', sessionId)
    93→        .eq('used', false)
    94→        .eq('user_id', user.id)
    95→        .eq('difficulty', difficulty)
    96→        .select('start_time')
    97→        .single();
    98→
    99→      // null → 세션 없음 / 이미 사용됨 / 소유자 불일치 / 난이도 불일치 중 하나
   100→      if (!session) {
   101→        return new Response(
   102→          JSON.stringify({ error: 'Invalid or already used session' }),
   103→          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   104→        );
   105→      }
   106→
   107→      // 서버 시각 기준 경과 시간으로 점수 타당성 검증
   108→      const elapsedMs = Date.now() - new Date(session.start_time).getTime();
   109→      const elapsedSec = elapsedMs / 1000;
   110→
   111→      // 세션 만료 체크 (2시간 초과)
   112→      if (elapsedMs > 2 * 60 * 60 * 1000) {
   113→        return new Response(
   114→          JSON.stringify({ error: 'Session expired' }),
   115→          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   116→        );
   117→      }
   118→
   119→      // 핵심 검증: 이 점수가 나오려면 최소 N초는 걸렸어야 함
   120→      // 보너스 아이템(금똥/다이아/토파즈/무지개)은 시간 없이도 점수를 올리므로 제외
   121→      // 1점 = 100ms → timeBasedScore점 = timeBasedScore * 0.1초, 50% 여유 적용
   122→      const bonusScore =
   123→        (verification?.goldCollected ?? 0) * 20 +
   124→        (verification?.diamondCollected ?? 0) * 40 +
   125→        (verification?.topazCollected ?? 0) * 80 +
   126→        (verification?.rainbowCollected ?? 0) * 90;
   127→      const timeBasedScore = Math.max(0, score - bonusScore);
   128→      const minRequiredSec = timeBasedScore * 0.1 * 0.5;
   129→      if (elapsedSec < minRequiredSec) {
   130→        console.warn('Session time gate failed', { score, elapsedSec, minRequiredSec });
   131→        return new Response(
   132→          JSON.stringify({ error: 'Score not achievable in elapsed time' }),
   133→          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   134→        );
   135→      }
   136→    } else if (verification) {
   137→      // 세션 없이 구 방식 verification만 있는 경우 (하위 호환)
   138→      const {
   139→        gameStartTime,
   140→        gameEndTime,
   141→        goldCollected = 0,
   142→        diamondCollected = 0,
   143→        topazCollected = 0,
   144→        rainbowCollected = 0,
   145→      } = verification;
   146→
   147→      const playDuration = gameEndTime - gameStartTime;
   148→      const timeScore = Math.floor(playDuration / 100);
   149→      const bonusScore =
   150→        goldCollected * 20 +
   151→        diamondCollected * 40 +
   152→        topazCollected * 80 +
   153→        rainbowCollected * 90;
   154→      const expectedScore = timeScore + bonusScore;
   155→      const tolerance = Math.max(expectedScore * 0.2, 10);
   156→
   157→      if (score > expectedScore + tolerance) {
   158→        console.warn('Score verification failed', { score, expectedScore, playDuration });
   159→        return new Response(
   160→          JSON.stringify({ error: 'Score verification failed' }),
   161→          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   162→        );
   163→      }
   164→    }
   165→
   166→    // profiles 테이블에 이니셜 업데이트
   167→    await supabaseAdmin
   168→      .from('profiles')
   169→      .update({ initials: userName })
   170→      .eq('id', user.id);
   171→
   172→    // 기존 점수 조회
   173→    const { data: existing } = await supabaseAdmin
   174→      .from('leaderboard')
   175→      .select('score')
   176→      .eq('user_id', user.id)
   177→      .eq('difficulty', difficulty)
   178→      .single();
   179→
   180→    const previousScore = existing?.score ?? null;
   181→    const isNewRecord = previousScore === null || score > previousScore;
   182→
   183→    // 최고 점수만 저장 (upsert)
   184→    if (isNewRecord) {
   185→      const validCharacterTypes = [
   186→        'chibi',
   187→        'log', 'swap', 'sum', 'fork', 'seed', 'session', 'branch', 'hook', 'socket', 'index',
   188→        'hacker', 'miner', 'maehwa', 'archieve', 'glitch', 'noise',
   189→        'sentinel', 'legacy',
   190→      ];
   191→      const safeCharacterType = validCharacterTypes.includes(characterType) ? characterType : 'chibi';
   192→
   193→      const { error: upsertError } = await supabaseAdmin
   194→        .from('leaderboard')
   195→        .upsert(
   196→          {
   197→            user_id: user.id,
   198→            difficulty,
   199→            score,
   200→            character_type: safeCharacterType,
   201→            updated_at: new Date().toISOString(),
   202→          },
   203→          { onConflict: 'user_id,difficulty' }
   204→        );
   205→
   206→      if (upsertError) {
   207→        console.error('Upsert error:', upsertError);
   208→        return new Response(
   209→          JSON.stringify({ error: 'Failed to save score' }),
   210→          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   211→        );
   212→      }
   213→    }
   214→
   215→    // 현재 순위 계산
   216→    const { count: rank } = await supabaseAdmin
   217→      .from('leaderboard')
   218→      .select('*', { count: 'exact', head: true })
   219→      .eq('difficulty', difficulty)
   220→      .gt('score', isNewRecord ? score : (previousScore ?? 0));
   221→
   222→    return new Response(
   223→      JSON.stringify({
   224→        success: true,
   225→        isNewRecord,
   226→        previousScore,
   227→        newScore: isNewRecord ? score : (previousScore ?? score),
   228→        rank: rank !== null ? rank + 1 : null,
   229→      }),
   230→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   231→    );
   232→  } catch (error) {
   233→    console.error('Unexpected error:', error);
   234→    return new Response(
   235→      JSON.stringify({ error: 'Internal server error' }),
   236→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   237→    );
   238→  }
   239→});
   240→

