   293→  private setupChannelListeners() {
   294→    if (!this.battleChannel) return;
   295→
   296→    // Presence join — 호스트일 때 상대 입장 UI 갱신 + 즉시 ready 전송
   297→    this.battleChannel.onPresenceJoin(() => {
   298→      if (this.isHost && !this.myReady) {
   299→        this.doSendReady();
   300→      }
