   311→    // READY 수신 = 상대가 확실히 존재 + 준비 완료
   312→    // Presence join보다 READY가 먼저 올 수 있으므로, 여기서도 자신의 ready를 보냄
   313→    this.battleChannel.onEvent(BattleEvent.READY, () => {
