   330→  /** ready 전송 (UI 상태와 분리 — 어디서든 호출 가능) */
   331→  private doSendReady() {
   332→    if (!this.battleChannel || this.myReady) return;
   333→    this.myReady = true;
   334→    const charId = getSafeSelectedCharacter();
   335→    this.battleChannel.sendReady(charId);
   336→
