   347→
   348→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   349→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   350→    this.clearReadyRetry();
   351→    this.readyRetryTimer = setInterval(() => {
   352→      if (this.countdownStarted || !this.battleChannel) {
   353→        this.clearReadyRetry();
   354→        return;
   355→      }
   356→      this.battleChannel.sendReady(charId);
