   361→
   362→  private clearReadyRetry() {
   363→    if (this.readyRetryTimer) {
   364→      clearInterval(this.readyRetryTimer);
   365→      this.readyRetryTimer = null;
   366→    }
   367→  }
   368→
   369→  private checkBothReady() {
   370→    if (this.myReady && this.opponentReady && this.isHost && !this.countdownStarted) {
   371→      this.countdownStarted = true;
   372→      this.battleChannel?.sendGameStart(Date.now());
   373→      this.showCountdown();
   374→    }
   375→  }
