   379→  private showCountdown() {
   380→    this.clearUI();
   381→
   382→    let count = 3;
   383→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   384→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
