   396→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   397→          timer.remove();
   398→          this.time.delayedCall(500, () => this.goToBattle());
   399→        }
   400→      },
   401→      repeat: 2,
   402→    });
   403→  }
   404→
   405→  // ─── 씬 전환 ──────────────────────────────────────────────────
   406→
   407→  private goToBattle() {
