   122→      const bonusScore =
   123→        (verification?.goldCollected ?? 0) * 20 +
   124→        (verification?.diamondCollected ?? 0) * 40 +
   125→        (verification?.topazCollected ?? 0) * 80 +
   126→        (verification?.rainbowCollected ?? 0) * 90;
   127→      const timeBasedScore = Math.max(0, score - bonusScore);
