     1→import type Phaser from 'phaser';
     2→import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
     3→import { getLeaderboard, type LeaderboardEntry } from '../utils/leaderboard';
     4→import BaseScene from './BaseScene';
     5→
     6→export default class LeaderboardScene extends BaseScene {
     7→  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
     8→  private leaderboardData: LeaderboardEntry[] = [];
     9→  private leaderboardTexts: Phaser.GameObjects.Text[] = [];
    10→  private loadingText?: Phaser.GameObjects.Text;
    11→  private errorText?: Phaser.GameObjects.Text;
    12→  private currentRequestId: number = 0; // 요청 추적용 ID
    13→  private difficultyButtons = new Map<Difficulty, Phaser.GameObjects.Rectangle>();
    14→
    15→  constructor() {
    16→    super('LeaderboardScene');
    17→  }
    18→
    19→  init() {
    20→    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
    21→    if (last) {
    22→      this.selectedDifficulty = last;
    23→    }
    24→  }
    25→
    26→  preload() {
    27→    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
    28→    if (!this.textures.exists('background2')) {
    29→      this.load.image('background2', 'assets/backgrounds/background2.webp');
    30→    }
    31→  }
    32→
    33→  create() {
    34→    super.create();
    35→
    36→    // 배경 이미지 추가
    37→    const background = this.add.image(200, 300, 'background2');
    38→    background.setDisplaySize(400, 600);
    39→
    40→    // 타이틀
    41→    this.add.text(200, 40, '🏆 랭킹보드 🏆', {
    42→      fontSize: '28px',
    43→      color: '#fff',
    44→      fontStyle: 'bold',
    45→      stroke: '#000',
    46→      strokeThickness: 5
    47→    }).setOrigin(0.5);
    48→
    49→    // 난이도 선택 버튼들
    50→    this.createDifficultyButtons();
    51→
    52→    // 랭킹 표시 영역 (초기 로딩)
    53→    this.loadingText = this.add.text(200, 300, '로딩 중...', {
    54→      fontSize: '20px',
    55→      color: '#fff',
    56→      stroke: '#000',
    57→      strokeThickness: 3
    58→    }).setOrigin(0.5);
    59→
    60→    // 뒤로가기 버튼
    61→    this.createBackButton();
    62→
    63→    // 초기 데이터 로드
    64→    this.loadLeaderboard();
    65→  }
    66→
    67→  private createDifficultyButtons() {
    68→    this.difficultyButtons.forEach(btn => btn.destroy());
    69→    this.difficultyButtons.clear();
    70→
    71→    const difficulties: Difficulty[] = [
    72→      DifficultyEnum.NORMAL,
    73→      DifficultyEnum.HARD,
    74→      DifficultyEnum.EXTREME,
    75→      DifficultyEnum.PHYSICAL
    76→    ];
    77→
    78→    const buttonWidth = 70;
    79→    const spacing = 85;
    80→    const startX = 200 - (spacing * 1.5);
    81→    const y = 95;
    82→
    83→    difficulties.forEach((difficulty, index) => {
    84→      const x = startX + (index * spacing);
    85→      const isSelected = difficulty === this.selectedDifficulty;
    86→
    87→      const button = this.add.rectangle(
    88→        x,
    89→        y,
    90→        buttonWidth,
    91→        35,
    92→        isSelected ? 0xffff99 : 0xffffff,
    93→        1
    94→      );
    95→      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
    96→
    97→      this.add.text(x, y, difficulty, {
    98→        fontSize: '12px',
    99→        color: '#000',
   100→        fontStyle: 'bold'
   101→      }).setOrigin(0.5);
   102→
   103→      this.difficultyButtons.set(difficulty, button);
   104→      button.setInteractive({ useHandCursor: true });
   105→
   106→      button.on('pointerover', () => {
   107→        if (difficulty !== this.selectedDifficulty) {
   108→          button.setFillStyle(0xffffcc);
   109→        }
   110→      });
   111→
   112→      button.on('pointerout', () => {
   113→        if (difficulty !== this.selectedDifficulty) {
   114→          button.setFillStyle(0xffffff);
   115→        }
   116→      });
   117→
   118→      button.on('pointerdown', () => {
   119→        this.selectDifficulty(difficulty);
   120→      });
   121→    });
   122→  }
   123→
   124→  private selectDifficulty(difficulty: Difficulty) {
   125→    // 같은 난이도면 무시
   126→    if (this.selectedDifficulty === difficulty) {
   127→      return;
   128→    }
   129→
   130→    this.selectedDifficulty = difficulty;
   131→
   132→    // 모든 버튼 스타일 재설정
   133→    this.difficultyButtons.forEach((btn, diff) => {
   134→      const isSelected = diff === difficulty;
   135→      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
   136→      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
   137→    });
   138→
   139→    // 새로운 난이도 데이터 로드
   140→    this.loadLeaderboard();
   141→  }
   142→
   143→  private async loadLeaderboard() {
   144→    // 요청 ID 증가 (새로운 요청 시작)
   145→    this.currentRequestId++;
   146→    const requestId = this.currentRequestId;
   147→
   148→    // 기존 랭킹 텍스트 제거
   149→    this.leaderboardTexts.forEach(text => text.destroy());
   150→    this.leaderboardTexts = [];
