import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { limit: limitParam } = await req.json().catch(() => ({}));
    const safeLimit = Math.min(Math.max(1, parseInt(limitParam ?? '20', 10)), 100);

    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
    const authHeader = req.headers.get('Authorization');
    let currentUserId: string | null = null;

    if (authHeader) {
      const supabaseUser = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
        { global: { headers: { Authorization: authHeader } } }
      );
      const { data: { user } } = await supabaseUser.auth.getUser();
      currentUserId = user?.id ?? null;
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // 랭킹 뷰 조회 (뷰 내부에서 복합 정렬 처리)
    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
      .from('battle_leaderboard_view')
      .select('user_id, wins, losses, disconnects, total_wins, win_rate, initials')
      .limit(safeLimit);

    if (leaderboardError) {
      console.error('Leaderboard query error:', leaderboardError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const entries = (leaderboard ?? []).map((entry, index) => ({
      rank: index + 1,
      userId: entry.user_id,
      userName: (entry.initials as string | null) ?? '???',
      wins: entry.wins,
      losses: entry.losses,
      disconnects: entry.disconnects,
      totalWins: entry.total_wins,
      winRate: Number(entry.win_rate),
    }));

    // 현재 유저 순위 조회
    let currentUserRank: { rank: number; totalWins: number; winRate: number } | null = null;
    if (currentUserId) {
      const { data: userRecord } = await supabaseAdmin
        .from('battle_records')
        .select('wins, losses, disconnects')
        .eq('user_id', currentUserId)
        .single();

      if (userRecord) {
        const totalWins = userRecord.wins + userRecord.disconnects;
        const { data: rankResult } = await supabaseAdmin
          .rpc('get_battle_rank', { p_total_wins: totalWins });

        const totalGames = userRecord.wins + userRecord.losses + userRecord.disconnects;
        const winRate = totalGames === 0
          ? 0
          : Math.round(totalWins / totalGames * 1000) / 10;

        currentUserRank = {
          rank: Number(rankResult ?? 0) + 1,
          totalWins,
          winRate,
        };
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        leaderboard: entries,
        currentUserRank,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

